function burstHearts(button){if(document.body.dataset.anim==="off")return;for(var i=0;i<6;i++){var s=el("span","hb");s.innerHTML=ic("heart");var ang=(Math.PI*2/6)*i+Math.random()*0.4;var dist=26+Math.random()*16;s.style.setProperty("--dx",Math.cos(ang)*dist+"px");s.style.setProperty("--dy",Math.sin(ang)*dist+"px");s.style.animationDelay=(i*28)+"ms";button.appendChild(s);setTimeout(function(node){return function(){if(node.parentNode)node.remove();};}(s),900);}}
