function showConfirm(title,msg,onYes,yesLabel){if(typeof msg==="function"){yesLabel=onYes;onYes=msg;msg="Cette action est irréversible.";}var t=$("confirm-title");if(t)t.textContent=title;var b=$("confirm-body");if(b)b.innerHTML='<p style="font-size:15px;line-height:1.6;">'+esc(msg)+"</p>";var f=$("confirm-foot");if(!f)return;f.innerHTML="";var no=el("button","","<span>Annuler</span>");no.addEventListener("click",function(){hideOverlay("confirm-overlay");});var yes=el("button","primary","<span>"+esc(yesLabel||"Confirmer")+"</span>");yes.addEventListener("click",function(){hideOverlay("confirm-overlay");if(onYes)onYes();});f.appendChild(no);f.appendChild(yes);showOverlay("confirm-overlay");}
