function updateJournalBadge(){var total=0;ST.entries.forEach(function(e){total+=(e.journal||[]).length;});var badge=$("journal-badge");if(!badge)return;if(ST.lastJournalCount===0){badge.style.display="none";ST.lastJournalCount=total;return;}if(total>ST.lastJournalCount&&ST.view!=="journal")badge.style.display="block";else badge.style.display="none";ST.lastJournalCount=total;}

function neonClass(e){if(e.aVoir)return"n-voir";if(e.enCours)return"n-enc";return"n-fini";}
function statIcon(e){if(e.aVoir)return ic("eye");if(e.enCours)return ic("hourglass");return ic("check");}
