function toInputDate(s){var p=parseDateFR(s);if(!p)return"";return p.y+"-"+pad2(p.mo)+"-"+pad2(p.d);}
function openPosterZoom(url){if(!url)return;var img=$("poster-img");if(img)img.src=url;showOverlay("poster-overlay");}
