function ghB64decode(s){return decodeURIComponent(escape(atob(s)));}
async function ghGetFile(c,path){var r=await fetch("https://api.github.com/repos/"+c.owner+"/"+c.repo+"/contents/"+path,{headers:{Authorization:"Bearer "+c.token,Accept:"application/vnd.github+json"}});if(r.status===404)return null;if(!r.ok)throw new Error("GET "+r.status);return await r.json();}
async function ghPutFile(c,path,content){var cur=await ghGetFile(c,path);var body={message:"Backup auto "+new Date().toISOString(),content:ghB64encode(content)};if(cur&&cur.sha)body.sha=cur.sha;var r=await fetch("https://api.github.com/repos/"+c.owner+"/"+c.repo+"/contents/"+path,{method:"PUT",headers:{Authorization:"Bearer "+c.token,Accept:"application/vnd.github+json","Content-Type":"application/json"},body:JSON.stringify(body)});if(!r.ok)throw new Error("PUT "+r.status);return await r.json();}
var ghTimer=null;
function scheduleGitHubBackup(){var c=ghConfig();if(!c.owner||!c.repo||!c.token)return;if(ghTimer)clearTimeout(ghTimer);ghTimer=setTimeout(function(){ghBackupNow(false);},5000);}
function dumpLists(){var o={};LIST_KEYS.forEach(function(k){o[k]=getList(k);});return o;}
async function ghBackupNow(manual){var c=ghConfig();if(!c.owner||!c.repo||!c.token){if(manual)toast("Configure GitHub dans Options.");return;}var data={version:"V0.9.3",exportDate:new Date().toISOString(),settings:settingsLoad(),lists:dumpLists(),customIcons:getCustomIcons(),entries:ST.entries};try{await ghPutFile(c,"sauvegarde.json",JSON.stringify(data));localStorage.setItem("last_gh_backup",String(Date.now()));if(manual)toast("Sauvegarde GitHub OK");}catch(e){if(manual)toast("Erreur GitHub : "+e.message,3000);}}
async function ghTest(){var c=ghConfig();if(!c.owner||!c.repo||!c.token){toast("Remplis owner, repo et token.");return;}try{var r=await fetch("https://api.github.com/repos/"+c.owner+"/"+c.repo,{headers:{Authorization:"Bearer "+c.token,Accept:"application/vnd.github+json"}});if(r.ok){var d=await r.json();toast("Connexion OK : "+d.full_name+(d.private?" (privé)":" (PUBLIC !)"));}else toast("Erreur "+r.status,3000);}catch(e){toast("Réseau impossible",3000);}}
async function ghRestore(){var c=ghConfig();if(!c.owner||!c.repo||!c.token){toast("Configure GitHub dans Options.");return;}try{var f=await ghGetFile(c,"sauvegarde.json");if(!f){toast("Aucune sauvegarde trouvée.",3000);return;}var data=JSON.parse(ghB64decode(f.content));var list=data.entries||[],ids={};ST.entries.forEach(function(x){ids[x.id]=1;});var added=0;for(var i=0;i<list.length;i++){var en=list[i];if(en&&en.id&&!ids[en.id]){if(!en.titre)en.titre="Sans titre";if(!en.dateAjout)en.dateAjout=new Date().toISOString();await dbPut(en);added++;}}if(data.settings)settingsSave(Object.assign({},SETTINGS_DEFAULTS,data.settings));if(data.lists)LIST_KEYS.forEach(function(k){if(Array.isArray(data.lists[k])&&data.lists[k].length)setList(k,data.lists[k]);});if(data.customTypes)importLegacyList("types",data.customTypes);if(data.customLists){importLegacyList("plateformes",data.customLists.plateformes);importLegacyList("supports",data.customLists.supports);importLegacyList("packagings",data.customLists.packagings);importLegacyList("bonus",data.customLists.bonus);}if(data.customIcons)setCustomIcons(data.customIcons);applySettings();buildTypeDropdown();refreshAll();toast("Restauré : "+added+" œuvre(s) ajoutée(s)");}catch(e){toast("Restauration impossible : "+e.message,3000);}}